 // Android uses a singleTask Activity. A killed WebView renderer must reclaim its
 // own wallet immediately; browser tabs still require the normal 30-second lease.
 const soleNativeActivity=typeof window!=='undefined'&&Boolean(window.NeonBridge);
 if(current&&current.token!==INSTANCE_TOKEN&&Number.isFinite(current.at)&&current.at<=now&&now-current.at<INSTANCE_TTL&&!soleNativeActivity)return false;
 try{localStorage.setItem(INSTANCE_KEY,JSON.stringify({token:INSTANCE_TOKEN,at:now}));const after=leaseRead();return Boolean(after&&after.token===INSTANCE_TOKEN)}
