// Recovery of interrupted wagers must happen independently in each wallet.
for(const mode of ['free','daily']){
 const p=profileSnapshots[mode];
 if(p.reserved){p.balance=Math.min(BALANCE_CAP,p.balance+p.reserved);p.reserved=0}
}
