function currentProfile(){return {balance:state.balance,reserved:state.reserved,stats:state.stats,rouletteHistory:state.rouletteHistory,activity:state.activity,gameStats:state.gameStats}}
function save(){
 if(!canModify())return false;
 if(volatileMode){profileSnapshots[state.mode]=currentProfile();return true}
 profileSnapshots[state.mode]=currentProfile();
 try{localStorage.setItem(STORAGE,JSON.stringify({...currentProfile(),mode:state.mode,profiles:profileSnapshots,dailyProgress}));return true}
 catch(e){instanceStorageAvailable=false;instanceWritable=false;return false}
}
// QA 1.7.2: memory and persistent wallet must agree even if a write fails.
// Capture both profiles because a mode switch, import or reset modifies both.
function walletCheckpoint(){return JSON.parse(JSON.stringify({mode:state.mode,current:currentProfile(),free:profileSnapshots.free,daily:profileSnapshots.daily,progress:dailyProgress}))}
function walletRestore(checkpoint){
 state.mode=checkpoint.mode;
 Object.assign(state,checkpoint.current);
 profileSnapshots.free=checkpoint.free;
 profileSnapshots.daily=checkpoint.daily;
 dailyProgress=checkpoint.progress;
}
function commitWallet(checkpoint){
 if(save())return true;
 walletRestore(checkpoint);
 updateBalance();leaseBlock();return false;
}
function switchMode(mode){
 if(!canModify()){leaseBlock();return}
 if(!['daily','free'].includes(mode)||mode===state.mode)return;
 if(state.reserved>0&&!confirm('Есть незавершённые ставки. Отменить их и вернуть фишки перед переключением режима?'))return;
 const previous=walletCheckpoint();
 if(state.reserved>0){state.balance=Math.min(BALANCE_CAP,state.balance+state.reserved);state.reserved=0}
 profileSnapshots[state.mode]=currentProfile();
 state.mode=mode;
 Object.assign(state,safeProfile(profileSnapshots[mode],mode==='daily'?DAILY_CREDIT:50000));
 if(!commitWallet(previous))return;
 resetRuntime();state.modal=null;render();toast(mode==='daily'?`Режим «Игровые дни»: день ${dailyProgress.day}`:'Свободный режим с пополнением фишек');
}
function finishDailyDay(reason='manual'){
 if(!canModify()){leaseBlock();return false}
 if(state.mode!=='daily')return false;
 if(state.reserved>0){toast('Сначала заверши ставки или отмени их на игровом столе.',true);return false}
 if(reason==='manual'&&!confirm(`Завершить день ${dailyProgress.day}? Остаток ${money(state.balance)} сгорит; на следующий день выдаётся ${money(DAILY_CREDIT)}.`))return false;
 const previous=walletCheckpoint();
 dailyProgress.history.unshift({day:dailyProgress.day,rounds:dailyProgress.rounds,wagered:dailyProgress.wagered,paid:dailyProgress.paid,leftover:state.balance,reason:reason==='empty'?'empty':'manual',at:Date.now()});
 dailyProgress.history=dailyProgress.history.slice(0,DAILY_HISTORY_LIMIT);
 dailyProgress.day=dailyProgress.day>=100000000?1:dailyProgress.day+1;dailyProgress.rounds=0;dailyProgress.wagered=0;dailyProgress.paid=0;dailyProgress.startedAt=Date.now();
 state.balance=DAILY_CREDIT;state.reserved=0;
 if(!commitWallet(previous))return false;
 resetRuntime();state.modal=null;render();
 toast(`День ${dailyProgress.day}: начислено ${money(DAILY_CREDIT)}.`);return true;
}
function modeBarHTML(){const daily=state.mode==='daily';return `<div class="mode-card"><div class="mode-row"><div class="mode-title">РЕЖИМ ИГРЫ <span class="mode-help">Без настоящих денег</span></div><div class="mode-buttons"><button class="mode-choice ${daily?'':'active'}" data-action="mode-free" aria-pressed="${!daily}">∞ Свободный</button><button class="mode-choice ${daily?'active':''}" data-action="mode-daily" aria-pressed="${daily}">◷ Игровые дни</button></div></div>${daily?`<div class="daily-row"><div><strong>ДЕНЬ ${dailyProgress.day}</strong><span> На день: ${money(DAILY_CREDIT)} · Остаток: <b>${money(state.balance)}</b> · Сыграно раундов: ${dailyProgress.rounds}</span></div><div class="daily-actions"><button class="btn small" data-action="daily-history">История дней</button><button class="btn gold small" data-action="daily-next" ${state.reserved?'disabled title="Сначала завершите все ставки"':''}>Завершить день</button></div></div>`:`<div class="free-note">Пополняй фишки сколько угодно. В режиме «Игровые дни» отдельный баланс, который невозможно пополнить вручную.</div>`}</div>`}
function renderModeBar(){const bar=document.getElementById('modeBar');if(bar)bar.innerHTML=modeBarHTML();const add=document.querySelector('.add-money');if(add)add.textContent=state.mode==='daily'?'◷':'＋';const label=document.querySelector('.wallet small');if(label)label.textContent=state.mode==='daily'?'ФИШКИ ЭТОГО ДНЯ':'МОЙ БАЛАНС'}
function rnd(max){if(max<=0)throw Error('Invalid random bound');if(globalThis.crypto?.getRandomValues){const limit=Math.floor(4294967296/max)*max;const a=new Uint32Array(1);do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%max}return Math.floor(Math.random()*max)}
function unit(){return (rnd(1000000000)+.5)/1000000000}
function spend(n){
 if(!canModify()){leaseBlock();return false}
 if(!Number.isSafeInteger(n)||n<=0||n>1000000||!Number.isSafeInteger(state.reserved+n))return false;
 if(state.balance<n){toast(state.mode==='daily'?'Недостаточно фишек. Заверши день и получи новый лимит.':'Недостаточно фишек. Пополни демо-баланс.',true);return false}
 state.balance-=n;state.reserved+=n;
 if(!save()){state.balance+=n;state.reserved-=n;leaseBlock();return false}
 updateBalance();return true
}
function refund(n){
 if(!canModify()){leaseBlock();return false}
 if(!Number.isSafeInteger(n)||n<=0||n>state.reserved)throw Error('Неверный возврат фишек');
 const previous=walletCheckpoint();
 state.balance=Math.min(BALANCE_CAP,state.balance+n);state.reserved-=n;
 if(!commitWallet(previous))return false;
 updateBalance();return true
}
function settle(game,stake,payout,detail=''){if(!canModify()){leaseBlock();return false}stake=Math.round(stake);payout=Math.max(0,Math.round(payout));if(!Number.isSafeInteger(stake)||stake<=0||!Number.isSafeInteger(payout)||stake>state.reserved)throw Error('Некорректный расчёт ставки');const previous=walletCheckpoint();state.reserved-=stake;state.balance=Math.min(BALANCE_CAP,state.balance+payout);state.stats.rounds=Math.min(BALANCE_CAP,state.stats.rounds+1);state.stats.wagered=Math.min(BALANCE_CAP,state.stats.wagered+stake);state.stats.paid=Math.min(BALANCE_CAP,state.stats.paid+payout);if(payout>stake)state.stats.wins=Math.min(BALANCE_CAP,state.stats.wins+1);const id=GAMES.find(x=>x.name===game)?.id||({ 'Блэкджек':'blackjack','Колесо':'wheel','Слоты':'slots','Монетка':'coin','Рулетка':'roulette','Баккара':'baccarat','Кено':'keno','Видеопокер':'poker','Рулетка Франции':'roulette-fr','Лотерея':'lotto','Скретч':'scratch','Сундуки':'treasure'})[game]||game.toLowerCase();const g=state.gameStats[id]||(state.gameStats[id]={rounds:0,wins:0,wagered:0,paid:0});g.rounds=Math.min(BALANCE_CAP,g.rounds+1);g.wagered=Math.min(BALANCE_CAP,g.wagered+stake);g.paid=Math.min(BALANCE_CAP,g.paid+payout);if(payout>stake)g.wins=Math.min(BALANCE_CAP,g.wins+1);state.activity.unshift({game,profit:payout-stake,detail,at:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});state.activity=state.activity.slice(0,20);
 if(state.mode==='daily'){
  dailyProgress.rounds=Math.min(BALANCE_CAP,dailyProgress.rounds+1);dailyProgress.wagered=Math.min(BALANCE_CAP,dailyProgress.wagered+stake);dailyProgress.paid=Math.min(BALANCE_CAP,dailyProgress.paid+payout);
 }
 if(!commitWallet(previous))return false;updateBalance();let net=payout-stake;toast(`${game}: ${net>0?'выигрыш +'+money(net):net<0?'−'+money(-net):'возврат ставки'}`,net<0);
 if(state.mode==='daily'&&state.balance<10&&state.reserved===0)finishDailyDay('empty');
 return true;
}
