let lastRenderedNavigation=null;
function render(){renderModeBar();let g=info(state.game);document.getElementById('headerGame').textContent=g.name.toUpperCase();document.getElementById('pageTitle').textContent=g.title;document.getElementById('pageSubtitle').textContent=g.sub;if(lastRenderedNavigation!==state.game){document.getElementById('gameNav').innerHTML=GAMES.map(x=>`<div class="nav-entry"><button class="nav-item ${x.id===state.game?'active':''}" data-action="nav" data-game="${x.id}"><span class="nav-ico">${x.icon}</span><span class="nav-game-name">${esc(x.name)}</span>${['crash','mines'].includes(x.id)?'<span class="nav-tag">HOT</span>':''}</button><button class="favorite-toggle ${favoriteGames.has(x.id)?'is-favorite':''}" type="button" data-action="favorite-toggle" data-game="${x.id}" aria-pressed="${favoriteGames.has(x.id)}" aria-label="${favoriteGames.has(x.id)?'Убрать из избранного: ':'Добавить в избранное: '}${esc(x.name)}">${favoriteGames.has(x.id)?'★':'☆'}</button></div>`).join('');lastRenderedNavigation=state.game}document.getElementById('gameArea').innerHTML=gameHTML();document.getElementById('rightPanel').innerHTML=rightHTML();updateBalance();if(typeof document.querySelectorAll==='function'){document.querySelectorAll('.feature-game').forEach(el=>el.classList.toggle('active',el.dataset.game===state.game));syncGameSearch()}renderModal();if(state.game==='plinko')drawPlinko();if(state.game==='crash'&&rt.crash?.active)updateCrashVisual()}
function gameHTML(){switch(state.game){case'roulette':return rouletteHTML();case'blackjack':return blackjackHTML();case'wheel':return luckyHTML();case'crash':return crashHTML();case'slots':return slotsHTML();case'mines':return minesHTML();case'plinko':return plinkoHTML();case'dice':return diceHTML();case'baccarat':return baccaratHTML();case'coin':return coinHTML();case'keno':return kenoHTML();case'poker':return pokerHTML();case'sicbo':return sicboHTML();case'limbo':return limboHTML();case'hilo':return hiloHTML();case'craps':return crapsHTML();case'roulette-us':return variantRouletteHTML('us');case'roulette-fr':return variantRouletteHTML('fr');case'threecard':return threecardHTML();case'war':return warHTML();case'dragontiger':return dragonHTML();case'tower':return towerHTML();case'bingo':return bingoHTML();case'lotto':return lottoHTML();case'scratch':return scratchHTML();case'seven':return sevenHTML();case'dicepoker':return dicePokerHTML();case'treasure':return treasureHTML();default:return''}}
function amountHTML(){return `<span class="panel-label">РАЗМЕР СТАВКИ (◈)</span><div class="amount-line"><button class="amount-step" data-action="amount-step" data-delta="-1">−</button><input id="stakeInput" class="amount-input" type="number" step="10" min="10" max="1000000" value="${state.stake}" aria-label="Ставка"><button class="amount-step" data-action="amount-step" data-delta="1">+</button></div><div class="quick-amounts">${[10,100,500,1000,5000].map(n=>`<button class="chip-quick ${state.stake===n?'active':''}" data-action="set-stake" data-value="${n}">${fmt(n)}</button>`).join('')}</div>`}
function betPanel(buttonLabel='ИГРАТЬ',action='generic-play',disabled=false,extra=''){return `<div class="panel"><div class="panel-header"><h3>Управление ставкой</h3><span class="subcap">ВИРТУАЛЬНЫЕ ФИШКИ</span></div><div class="panel-body">${amountHTML()}${extra}<button class="btn primary block" style="margin-top:16px" data-action="${action}" ${disabled?'disabled':''}>${buttonLabel}</button></div></div>`}
function rightHTML(){const rules={roulette:'<strong>Европейская рулетка:</strong> один зеро (0), 37 ячеек. Число — 35:1; цвет, чёт/нечёт, 1–18/19–36 — 1:1; дюжина и колонка — 2:1. Ставки суммируются. Нажми на число или сектор стола.',blackjack:'<strong>Блэкджек:</strong> приблизься к 21, не перебирая. Туз = 1 или 11. Дилер стоит на любых 17. Натуральный 21 платит 3:2. Двойная ставка — ровно одна карта; разделение доступно для пары одного ранга.',wheel:'<strong>Колесо:</strong> каждый из 24 секторов равновероятен. Выплата = ставка × показанный множитель (включая нулевые сектора).',crash:'<strong>Crash:</strong> множитель растёт, пока раунд внезапно не завершится. Нужно нажать «Забрать» до остановки. Серверов нет, результат генерируется локально; крайнее значение ×100.',slots:'<strong>Слоты:</strong> комбинации учитываются по трём горизонтальным и двум диагональным линиям. Три одинаковых символа дают выплату. Общая ставка делится на пять линий.',mines:'<strong>Mines:</strong> поля 4×4, 5×5, 4×8, 6×6, 7×7, 8×8, 10×10. Чем больше мин и открытых безопасных клеток, тем выше выплата. Можно забрать текущий выигрыш после первого успешного открытия.',plinko:'<strong>Plinko:</strong> шар проходит 8 случайных отклонений и попадает в один из девяти карманов. Множители указаны под полем. Каждый поворот равновероятен.',dice:'<strong>Dice:</strong> выбирай вероятность от 5% до 95% и ставь на число ниже либо выше порога. Выплата при победе = ставка × 0,97 / вероятность.',baccarat:'<strong>Баккара:</strong> ставка на игрока, банкира или ничью. Стандартные правила Punto Banco, третья карта добирается автоматически. Игрок — 1:1; банкир — 0,95:1; ничья — 8:1. При ничьей обычные ставки возвращаются.',coin:'<strong>Монетка:</strong> шансы 50/50, выплата при победе ×1,95. Каждый бросок независим.',keno:'<strong>Кено 5 из 40:</strong> отметь ровно 5 чисел. Система случайно выбирает 10 чисел из 40. Совпадения: 2 → ×2, 3 → ×2,5, 4 → ×12, 5 → ×200; остальные проигрывают.',poker:'<strong>Jacks or Better:</strong> получи пять карт, нажми на карты, которые хочешь оставить, затем замени остальные. Выплата за пару валетов и старше, две пары, тройку, стрит, флеш и старшие комбинации.',sicbo:'<strong>Sic Bo:</strong> три кубика, 35 вариантов ставок. Малое/большое исключают тройки (×2), любая тройка ×25, точная тройка ×181, суммы от 4 до 17, пары и отдельные числа имеют собственные коэффициенты.',limbo:'<strong>Limbo:</strong> сам выбираешь множитель. Вероятность достижения ×M равна 97% / M. Выигрышная выплата = ставка × M. Только виртуальные фишки.',hilo:'<strong>Выше / ниже:</strong> угадай, будет ли следующий ранг выше или ниже открытой карты. Ранги: A (низкий) – K. При равенстве возвращается ставка. Множитель учитывает количество подходящих рангов.',craps:'<strong>Craps:</strong> Pass Line — 7/11 побеждают сразу, 2/3/12 проигрывают; после пойнта нужно выбросить его до семёрки. Don’t Pass — 2/3 побеждают, 12 возвращает ставку, 7/11 проигрывают; после пойнта выигрывает семёрка. Победа ×2.'};Object.assign(rules,EXTRA_RULES,MORE_RULES);const stats=state.stats,gs=state.gameStats[state.game]||{rounds:0,wins:0,wagered:0,paid:0};const recent=state.activity.slice(0,5).map(a=>`<div class="act"><span>${esc(a.game)} <span class="muted">${esc(a.at)}</span></span><b class="${a.profit<0?'loss':''}">${a.profit>0?'+':''}${fmt(a.profit)}</b></div>`).join('');return `<div class="panel"><div class="panel-header"><h3>Твоя статистика</h3><span class="subcap">ВСЕ ИГРЫ</span></div><div class="panel-body"><div class="stats"><div class="stat"><span>Раундов</span><b>${fmt(stats.rounds)}</b></div><div class="stat"><span>Выигрышей</span><b class="accent">${fmt(stats.wins)}</b></div><div class="stat"><span>Всего ставок</span><b>${fmt(stats.wagered)}</b></div><div class="stat"><span>Чистый результат</span><b class="${stats.paid>=stats.wagered?'accent':'goldtext'}">${stats.paid>=stats.wagered?'+':''}${fmt(stats.paid-stats.wagered)}</b></div></div><div class="stats game-stats"><div class="stat"><span>В этой игре</span><b>${fmt(gs.rounds)} раундов</b></div><div class="stat"><span>Результат игры</span><b class="${gs.paid>=gs.wagered?'accent':'goldtext'}">${gs.paid>=gs.wagered?'+':''}${fmt(gs.paid-gs.wagered)}</b></div></div><button class="btn ghost small block" style="margin-top:13px" data-action="wallet">${state.mode==='daily'?'◷ Правила игрового дня':'＋ Выдать себе фишки'}</button></div></div><div class="panel"><div class="panel-header"><h3>Правила игры</h3><span class="subcap">КАК ИГРАТЬ</span></div><div class="panel-body"><div class="rules">${rules[state.game]}</div></div></div><div class="panel"><div class="panel-header"><h3>Последние результаты</h3><button class="link-btn" data-action="reset-stats">Сбросить</button></div><div class="panel-body"><div class="activity">${recent||'<div class="empty-note">Пока нет сыгранных раундов</div>'}</div></div></div>`}
function resultNote(msg,kind=''){return msg?`<div class="result-notice ${kind}">${esc(msg)}</div>`:''}
function outcomeColor(n){return n===0?'green':REDS.has(n)?'red':'black'}
function sectorSVG(labels,colors,size=300){const cnt=labels.length,sector=360/cnt,rad=size/2,outer=rad-6,center=rad;const parts=[];for(let i=0;i<cnt;i++){const a1=(-90+i*sector)*Math.PI/180,a2=(-90+(i+1)*sector)*Math.PI/180;let x1=center+outer*Math.cos(a1),y1=center+outer*Math.sin(a1),x2=center+outer*Math.cos(a2),y2=center+outer*Math.sin(a2);parts.push(`<path d="M ${center} ${center} L ${x1.toFixed(2)} ${y1.toFixed(2)} A ${outer} ${outer} 0 0 1 ${x2.toFixed(2)} ${y2.toFixed(2)} Z" fill="${colors[i]}" stroke="#f6e3ae" stroke-width="${cnt>20?.7:1.5}"/>`);const mid=(-90+(i+.5)*sector)*Math.PI/180;const tr=outer*(cnt>20?.79:.70);const x=center+tr*Math.cos(mid),y=center+tr*Math.sin(mid);parts.push(`<text x="${x.toFixed(2)}" y="${y.toFixed(2)}" font-size="${cnt>20?12:17}" font-weight="900" fill="white" text-anchor="middle" dominant-baseline="middle" transform="rotate(${(-90+(i+.5)*sector+90).toFixed(2)} ${x.toFixed(2)} ${y.toFixed(2)})">${labels[i]}</text>`)}return `<svg viewBox="0 0 ${size} ${size}" xmlns="http://www.w3.org/2000/svg" aria-label="Игровое колесо"><circle cx="${center}" cy="${center}" r="${rad-1}" fill="#9f8151" stroke="#cbb077" stroke-width="3"/>${parts.join('')}<circle cx="${center}" cy="${center}" r="${cnt>20?29:24}" fill="#163b3c" stroke="#d3ba75" stroke-width="6"/><circle cx="${center}" cy="${center}" r="7" fill="#f0d595"/></svg>`}
function tapeHTML(){const nums=rt.rouletteTape||[...Array(26)].map(()=>RNUM[rnd(37)]);return `<div class="tape-viewport"><div class="tape-cursor"></div><div id="tapeTrack" class="tape-track">${nums.map(n=>`<span class="tape-number ${outcomeColor(n)}">${n}</span>`).join('')}</div></div>`}
function rouletteHTML(){const last=rt.rouletteResult??state.rouletteHistory[0]?.n??'—';const latest=state.rouletteHistory.slice(0,10);const grouped=new Map();rt.bets.forEach(b=>{const k=b.type+':'+b.value;grouped.set(k,(grouped.get(k)||0)+b.amount)});const badge=(type,value)=>grouped.has(type+':'+value)?`<span class="bet-mark">${fmt(grouped.get(type+':'+value))}</span>`:'';let numCells='';for(let row=2;row>=0;row--)for(let col=0;col<12;col++){const n=col*3+row+1;numCells+=`<button class="bet-cell ${outcomeColor(n)}" data-action="roulette-bet" data-type="number" data-value="${n}" ${rt.rouletteSpinning?'disabled':''}>${n}${badge('number',n)}</button>`}const out=(text,type,value,extra='')=>`<button class="outside-bet ${extra}" data-action="roulette-bet" data-type="${type}" data-value="${value}" ${rt.rouletteSpinning?'disabled':''}>${text}${badge(type,value)}</button>`;return `<div class="hero-table"><div class="roulette-top"><div class="roulette-wheel-wrap"><div class="wheel-needle"></div><div class="roulette-wheel" id="rouletteWheel" style="transform:rotate(${rt.rouletteRotation}deg)">${sectorSVG(RNUM,RNUM.map(n=>n===0?'#11926f':REDS.has(n)?'#c13c4c':'#242938'))}</div></div><div class="roulette-display"><span class="panel-label">${rt.rouletteSpinning?'КОЛЕСО КРУТИТСЯ':'ПОСЛЕДНЕЕ ЧИСЛО'}</span><div class="center-result ${Number.isInteger(last)?outcomeColor(last):''}">${last}</div><h2>${rt.rouletteSpinning?'Ожидание результата…':'Ставь на удачу'}</h2><div class="tiny">Европейская рулетка · RTP ≈ 97,3%</div><button class="btn primary" data-action="roulette-spin" ${rt.rouletteSpinning||!rt.bets.length?'disabled':''}>◉ &nbsp; КРУТИТЬ КОЛЕСО</button></div></div>${tapeHTML()}<div class="history-strip"><span class="panel-label">ИСТОРИЯ</span><div class="history-numbers">${latest.map(x=>`<span class="ball-mini ${outcomeColor(x.n)}">${x.n}</span>`).join('')||'<span class="tiny">Нет вращений</span>'}</div><button class="link-btn" data-action="history">Вся история ›</button></div></div><div class="panel betting-panel"><div class="panel-header"><h2>Игровой стол</h2><span class="subcap">ВЫБЕРИ ФИШКУ И ЯЧЕЙКУ</span></div><div class="betting-content"><div class="roulette-board-scroll"><div class="roulette-grid-wrap"><button class="zero-cell" data-action="roulette-bet" data-type="number" data-value="0" ${rt.rouletteSpinning?'disabled':''}>0${badge('number',0)}</button><div class="number-grid">${numCells}</div></div><div class="outside-grid dozen">${out('1–12','dozen','1')}${out('13–24','dozen','2')}${out('25–36','dozen','3')}</div><div class="outside-grid">${out('1–18','low','low')}${out('ЧЁТ','even','even')}${out('🔴 КРАСНОЕ','color','red','red')}${out('⚫ ЧЁРНОЕ','color','black','black')}${out('НЕЧЁТ','odd','odd')}${out('19–36','high','high')}</div><div class="outside-grid dozen">${out('Колонка 1','column','1')}${out('Колонка 2','column','2')}${out('Колонка 3','column','3')}</div></div><p class="main-scroll-hint">↔ На телефоне стол можно прокручивать вбок</p><div class="chip-toolbar"><div class="chip-stack">${[10,50,100,500,1000].map(n=>`<button class="chip-button ${state.chip===n?'active':''}" data-action="chip" data-value="${n}" title="${n} фишек">${n>=1000?'1K':n}</button>`).join('')}</div><div class="button-row"><button class="btn small" data-action="roulette-undo" ${!rt.bets.length||rt.rouletteSpinning?'disabled':''}>↶ Отменить</button><button class="btn small ghost" data-action="roulette-clear" ${!rt.bets.length||rt.rouletteSpinning?'disabled':''}>Очистить</button></div></div><div class="wager-summary">Ставок: <b>${rt.bets.length}</b> · На столе: <b class="goldtext">${money(rt.bets.reduce((s,b)=>s+b.amount,0))}</b></div>${resultNote(rt.rouletteNotice,rt.rouletteNotice.startsWith('Выигрыш')?'win':'')}</div></div>`}
function wheelRotateTo(id,current,index,count,loops=6){const step=360/count;const target=(360-(index+.5)*step)%360;const extra=(target-((current%360+360)%360)+360)%360;const next=current+loops*360+extra;const el=document.getElementById(id);if(el){requestAnimationFrame(()=>{el.style.transform=`rotate(${next}deg)`})}return next}
function rouletteBet(type,value){if(rt.rouletteSpinning)return;const allowed={number:Number.isInteger(Number(value))&&Number(value)>=0&&Number(value)<=36,color:['red','black'].includes(value),low:value==='low',high:value==='high',odd:value==='odd',even:value==='even',dozen:['1','2','3'].includes(String(value)),column:['1','2','3'].includes(String(value))};if(!allowed[type]||![10,50,100,500,1000].includes(state.chip))return;if(!spend(state.chip))return;rt.bets.push({type,value,amount:state.chip});rt.rouletteNotice='';render()}
function rouletteWin(b,n){switch(b.type){case'number':return Number(b.value)===n?35:0;case'color':return outcomeColor(n)===b.value?1:0;case'low':return n>=1&&n<=18?1:0;case'high':return n>=19&&n<=36?1:0;case'even':return n!==0&&n%2===0?1:0;case'odd':return n%2===1?1:0;case'dozen':return n!==0&&Math.ceil(n/12)===Number(b.value)?2:0;case'column':return n!==0&&(n-1)%3+1===Number(b.value)?2:0;default:return 0}}
function spinRoulette(){if(rt.rouletteSpinning||!rt.bets.length)return;const epoch=roundEpoch;const n=rnd(37);const bets=rt.bets.splice(0);const stake=bets.reduce((s,b)=>s+b.amount,0);rt.rouletteSpinning=true;rt.rouletteNotice='';rt.rouletteTape=Array.from({length:65},()=>RNUM[rnd(37)]);rt.rouletteTape[52]=n;render();rt.rouletteRotation=wheelRotateTo('rouletteWheel',rt.rouletteRotation,RNUM.indexOf(n),37,7);const t=document.getElementById('tapeTrack'),viewport=t?.parentElement;if(t&&viewport){const targetX=-(52*64+30-viewport.clientWidth/2);requestAnimationFrame(()=>{t.style.transition='transform 4s cubic-bezier(.08,.75,.09,1)';t.style.transform=`translateX(${targetX}px)`})}setTimeout(()=>{if(epoch!==roundEpoch)return;const payout=bets.reduce((sum,b)=>sum+(rouletteWin(b,n)>0?b.amount*(1+rouletteWin(b,n)):0),0);rt.rouletteResult=n;rt.rouletteSpinning=false;rt.rouletteTape=null;state.rouletteHistory.unshift({n,at:Date.now(),stake,payout});state.rouletteHistory=state.rouletteHistory.slice(0,80);rt.rouletteNotice=payout>0?`Выигрыш: ${money(payout)} · выпало ${n}`:`Выпало ${n} · попробуй ещё раз`;settle('Рулетка',stake,payout,`Число ${n}`);if(state.game==='roulette')render()},4200)}
function newDeck(count=6){let cards=[];for(let k=0;k<count;k++)for(let r of RANKS)for(let suit of SUITS)cards.push({rank:r,suit});for(let i=cards.length-1;i>0;i--){let j=rnd(i+1);[cards[i],cards[j]]=[cards[j],cards[i]]}return cards}
function draw(deck){if(!deck.length)deck.push(...newDeck());return deck.pop()}
function cardVal(card){return card.rank==='A'?11:['J','Q','K'].includes(card.rank)?10:Number(card.rank)}
function handVal(cards){let points=cards.reduce((n,c)=>n+cardVal(c),0);let aces=cards.filter(c=>c.rank==='A').length;while(points>21&&aces>0){points-=10;aces--}return points}
function cardHTML(card,back=false){return `<div class="playing-card ${back?'back':(['♥','♦'].includes(card.suit)?'red':'')}"><span>${back?'?':card.rank}</span><span class="suit">${back?'✦':card.suit}</span></div>`}
function blackjackHTML(){const b=rt.bj;let stage=b?.stage||'idle';const done=stage==='done';let dealer=b?b.dealer:[],hands=b?.hands||[];let playable=stage==='playing';const active=hands[b?.active||0]||null;const canSplit=playable&&hands.length===1&&active.cards.length===2&&active.cards[0].rank===active.cards[1].rank&&state.balance>=active.stake;const canDouble=playable&&active?.cards.length===2&&state.balance>=active.stake;let controls=playable?`<div class="table-buttons"><button class="btn primary" data-action="bj-hit">ЕЩЁ КАРТУ</button><button class="btn gold" data-action="bj-stand">ХВАТИТ</button><button class="btn" data-action="bj-double" ${canDouble?'':'disabled'}>Удвоить</button><button class="btn" data-action="bj-split" ${canSplit?'':'disabled'}>Разделить</button></div>`:!b||done?`<div class="table-buttons"><button class="btn primary" data-action="bj-deal">${done?'НОВАЯ РАЗДАЧА':'РАЗДАТЬ КАРТЫ'}</button></div>`:'';let playerHTML=hands.length?`<div class="split-hands">${hands.map((h,i)=>`<div class="split-hand ${playable&&b.active===i?'active':''}"><div class="hand-info">${hands.length>1?'Рука '+(i+1):'ТВОИ КАРТЫ'} · ${handVal(h.cards)} очков · ${fmt(h.stake)} ◈</div><div class="hand">${h.cards.map(c=>cardHTML(c)).join('')}</div>${h.outcome?`<span class="status-pill ${h.payout>h.stake?'green':h.payout<h.stake?'red':''}">${h.outcome}</span>`:''}</div>`).join('')}</div>`:`<div class="hand"><div class="playing-card back"><span>?</span></div><div class="playing-card back"><span>?</span></div></div>`;return `<div class="card-felt"><div class="table-sign">BLACKJACK PAYS 3 TO 2 • DEALER STANDS ON 17</div><div class="hand-info">ДИЛЕР · ${b?(playable?cardVal(dealer[0]):handVal(dealer)):'—'} ${playable?'(вторая карта скрыта)':'очков'}</div><div class="hand">${dealer.length?dealer.map((c,i)=>cardHTML(c,playable&&i===1)).join(''):`${cardHTML({rank:'A',suit:'♠'},true)}${cardHTML({rank:'K',suit:'♥'},true)}`}</div><div class="table-sign" style="opacity:.7;margin:15px 0">✧ ───────────────── ✧</div>${playerHTML}<div class="center-message">${esc(b?.message||'Добро пожаловать за стол!')}</div>${controls}</div><div class="panel betting-panel"><div class="panel-header"><h3>Настройки раунда</h3><span class="subcap">СТАНДАРТНОЕ КАЗИНО</span></div><div class="panel-body">${amountHTML()}<p class="tiny">Натуральный блэкджек: ×2,5 к ставке · Победа: ×2 · Ничья: возврат. Выплата выполняется после окончания раздачи.</p></div></div>`}
function dealBlackjack(){if(rt.bj?.stage==='playing'){toast('Сначала закончи раздачу',true);return}if(!spend(state.stake))return;const deck=newDeck(),h=[draw(deck),draw(deck)],d=[draw(deck),draw(deck)];rt.bj={stage:'playing',deck,dealer:d,hands:[{cards:h,stake:state.stake,finished:false,fromSplit:false}],active:0,message:'Возьми карту или остановись'};if(handVal(h)===21||handVal(d)===21)finishBlackjack();else render()}
function nextBlackjack(){let b=rt.bj;const next=b.hands.findIndex((h,i)=>i>b.active&&!h.finished);if(next>=0){b.active=next;b.message='Играем следующую руку';render()}else finishBlackjack()}
function finishBlackjack(){const b=rt.bj;if(!b||b.stage!=='playing')return;const anyAlive=b.hands.some(h=>handVal(h.cards)<=21);if(anyAlive){while(handVal(b.dealer)<17)b.dealer.push(draw(b.deck))}const dealerScore=handVal(b.dealer),dealerNatural=b.dealer.length===2&&dealerScore===21;let payout=0,stake=0;b.hands.forEach(h=>{const v=handVal(h.cards),natural=!h.fromSplit&&h.cards.length===2&&v===21;let p=0,label='Проигрыш';if(v>21){label='Перебор'}else if(dealerNatural&&!natural){label='Дилер: блэкджек'}else if(natural&&!dealerNatural){p=Math.round(h.stake*2.5);label='БЛЭКДЖЕК ×2,5'}else if(dealerScore>21||v>dealerScore){p=h.stake*2;label='ПОБЕДА ×2'}else if(v===dealerScore){p=h.stake;label='НИЧЬЯ'}h.outcome=label;h.payout=p;payout+=p;stake+=h.stake});b.stage='done';b.message=payout>stake?`Выигрыш! +${money(payout-stake)}`:payout===stake?'Ничья · ставка возвращена':'Раунд окончен';settle('Блэкджек',stake,payout);if(state.game==='blackjack')render()}
function bjAction(action){const b=rt.bj;if(!b||b.stage!=='playing')return;const h=b.hands[b.active];if(action==='bj-hit'){h.cards.push(draw(b.deck));if(handVal(h.cards)>21){h.finished=true;nextBlackjack()}else if(handVal(h.cards)===21){h.finished=true;nextBlackjack()}else render()}else if(action==='bj-stand'){h.finished=true;nextBlackjack()}else if(action==='bj-double'){if(h.cards.length!==2||!spend(h.stake))return;h.stake*=2;h.cards.push(draw(b.deck));h.finished=true;nextBlackjack()}else if(action==='bj-split'){if(b.hands.length!==1||h.cards.length!==2||h.cards[0].rank!==h.cards[1].rank||!spend(h.stake))return;const c1=h.cards[0],c2=h.cards[1];b.hands=[{cards:[c1,draw(b.deck)],stake:h.stake,finished:false,fromSplit:true},{cards:[c2,draw(b.deck)],stake:h.stake,finished:false,fromSplit:true}];b.active=0;if(c1.rank==='A'){b.hands.forEach(x=>x.finished=true);finishBlackjack()}else render()}}
function luckyHTML(){return `<div class="panel"><div class="panel-header"><h2>Фортуна</h2><span class="status-pill ${rt.wheelSpinning?'':'green'}">${rt.wheelSpinning?'ВРАЩЕНИЕ':'ГОТОВО'}</span></div><div class="panel-body" style="text-align:center"><div class="lucky-wheel-wrap"><div class="lucky-wheel"><div class="wheel-needle"></div><div id="luckyWheelSvg" style="width:100%;height:100%;transform:rotate(${rt.wheelRotation}deg);transition:transform 3.8s cubic-bezier(.1,.7,.05,1)">${sectorSVG(WIN_SECTORS.map(x=>'×'+x),WIN_SECTORS.map((x,i)=>x===0?'#9a3954':x>=5?'#926e23':i%2===0?'#187767':'#6450a3'),340)}</div><div class="lucky-center">✦</div></div></div><div class="wheel-result">${rt.wheelResult==null?'КРУТИ И ВЫИГРЫВАЙ':'×'+rt.wheelResult}</div>${resultNote(rt.wheelNotice,rt.wheelResult>1?'win':'')}</div></div><div style="margin-top:17px">${betPanel(rt.wheelSpinning?'КОЛЕСО ВРАЩАЕТСЯ…':'✺ КРУТИТЬ КОЛЕСО','wheel-spin',rt.wheelSpinning)}</div>`}
function spinWheel(){if(rt.wheelSpinning||!spend(state.stake))return;const epoch=roundEpoch;const stake=state.stake,index=rnd(WIN_SECTORS.length),m=WIN_SECTORS[index];rt.wheelSpinning=true;rt.wheelNotice='';rt.wheelResult=null;render();rt.wheelRotation=wheelRotateTo('luckyWheelSvg',rt.wheelRotation,index,WIN_SECTORS.length,7);setTimeout(()=>{if(epoch!==roundEpoch)return;rt.wheelSpinning=false;rt.wheelResult=m;const payout=Math.round(stake*m);rt.wheelNotice=`Выпал сектор ×${m} · получено ${money(payout)}`;settle('Колесо',stake,payout,`×${m}`);if(state.game==='wheel')render()},4050)}
function crashHTML(){const c=rt.crash||{status:'idle',shown:1};const running=c.active;const val=running?c.shown:(c.last||1);const hist=(c.history||[]).slice(0,14);return `<div class="panel"><div class="panel-header"><h2>Множитель в реальном времени</h2><span class="status-pill ${running?'green':c.status==='crashed'?'red':''}">${running?'В ПОЛЁТЕ':c.status==='crashed'?'КРАШ':'ГОТОВО'}</span></div><div class="panel-body"><div class="crash-chart"><svg id="crashSvg" viewBox="0 0 500 300" preserveAspectRatio="none"><path class="crash-grid" d="M 0 60 H 500 M0 120 H500 M0 180 H500 M0 240 H500 M100 0 V300 M200 0 V300 M300 0 V300 M400 0 V300"/><path id="crashArea" d="" fill="#35d6bf24"/><path id="crashLine" d="" fill="none" stroke="#35d6bf" stroke-width="4" stroke-linecap="round"/></svg><div id="crashValue" class="crash-big ${c.status==='crashed'?'bust':''}">×${Number(val).toFixed(2)}</div><div id="crashHint" class="crash-hint">${running?'Забери фишки до остановки!':c.status==='crashed'?'Самолёт улетел — новый раунд ниже':'Нажми «Старт», чтобы начать'}</div></div><div class="history-strip"><span class="panel-label">ПРОШЛЫЕ РАУНДЫ</span><div class="history-numbers">${hist.map(x=>`<span class="status-pill ${x>=2?'green':x<1.2?'red':''}">×${x.toFixed(2)}</span>`).join('')||'<span class="muted tiny">История пуста</span>'}</div></div></div></div><div class="panel betting-panel"><div class="panel-header"><h3>Crash-ставка</h3><span class="subcap">ЗАБИРАЙ ВОВРЕМЯ</span></div><div class="panel-body">${amountHTML()}<button class="btn ${running?'gold':'primary'} block" data-action="${running?'crash-cash':'crash-start'}" style="margin-top:15px">${running?'✓ ЗАБРАТЬ ×'+c.shown.toFixed(2):'↗ НАЧАТЬ ПОЛЁТ'}</button><p class="tiny">Автоматического вывода нет. При завершении раунда ставка сгорает. Предельный множитель ×100.</p></div></div>`}
function startCrash(){if(rt.crash?.active)return;if(!spend(state.stake))return;let crashAt=unit()<.01?1:(.98/(1-unit()));crashAt=Math.min(100,Math.max(1.01,crashAt));let c=rt.crash||{history:[]};c.active=true;c.status='running';c.stake=state.stake;c.crashAt=crashAt;c.shown=1;c.started=performance.now();c.last=1;rt.crash=c;render();c.interval=setInterval(()=>{if(!c.active){clearInterval(c.interval);return}const elapsed=performance.now()-c.started;c.shown=Math.min(100,Math.exp(elapsed*.00045));if(c.shown>=c.crashAt){c.shown=c.crashAt;c.active=false;c.status='crashed';c.last=c.crashAt;c.history.unshift(c.crashAt);c.history=c.history.slice(0,20);clearInterval(c.interval);settle('Crash',c.stake,0,`Краш ×${c.crashAt.toFixed(2)}`);if(state.game==='crash')render();return}if(state.game==='crash')updateCrashVisual()},55)}
function cashCrash(){const c=rt.crash;if(!c?.active)return;c.shown=Math.min(100,Math.exp((performance.now()-c.started)*.00045));if(c.shown>=c.crashAt){c.active=false;c.status='crashed';c.last=c.crashAt;c.history.unshift(c.crashAt);clearInterval(c.interval);settle('Crash',c.stake,0,`Краш ×${c.crashAt.toFixed(2)}`)}else{c.active=false;c.status='cashed';c.last=c.shown;c.history.unshift(c.crashAt);clearInterval(c.interval);settle('Crash',c.stake,Math.round(c.stake*c.shown),`Вывод ×${c.shown.toFixed(2)}`)}if(state.game==='crash')render()}
function updateCrashVisual(){const c=rt.crash;if(!c)return;const v=document.getElementById('crashValue');if(v)v.textContent='×'+c.shown.toFixed(2);const cashBtn=document.querySelector('[data-action="crash-cash"]');if(cashBtn)cashBtn.textContent='✓ ЗАБРАТЬ ×'+c.shown.toFixed(2);const y0=275, maxY=Math.max(3,c.shown*1.15),points=[];const samples=80;for(let i=0;i<=samples;i++){const p=i/samples;const m=Math.exp(Math.log(Math.max(c.shown,1))*p),x=20+460*p,y=y0-(m-1)/(maxY-1)*245;points.push(`${i===0?'M':'L'} ${x.toFixed(1)} ${y.toFixed(1)}`)}const path=points.join(' '),line=document.getElementById('crashLine'),area=document.getElementById('crashArea');if(line)line.setAttribute('d',path);if(area)area.setAttribute('d',path+' L 480 275 L 20 275 Z')}
function slotsHTML(){const s=rt.slots||{cells:['🍒','🍋','💎','🍀','🔔','🍋','7️⃣','🍒','🍀'],notice:''};const won=new Set(s.wonIndices||[]);return `<div class="panel"><div class="panel-header"><h2>NEON SLOTS <span class="goldtext">777</span></h2><span class="status-pill ${s.spinning?'':'green'}">${s.spinning?'ВРАЩЕНИЕ':'5 ЛИНИЙ'}</span></div><div class="panel-body"><div class="slots-grid">${s.cells.map((icon,i)=>`<div class="slot-tile ${s.spinning?'spinning':''} ${won.has(i)?'win':''}" id="slot${i}">${icon}</div>`).join('')}</div><div class="slot-paytable" style="margin-top:16px">🍒 ×10 · 🍋 ×15 · 🔔 ×20 · 🍀 ×30 · 💎 ×45 · 7️⃣ ×85<br>Три одинаковых на линии · Выплата за линию = ставка ÷ 5 × множитель</div>${resultNote(s.notice,s.payout>s.stake?'win':s.payout===0?'lose':'')}</div></div><div style="margin-top:17px">${betPanel(s.spinning?'БАРАБАНЫ КРУТЯТСЯ…':'▦ КРУТИТЬ БАРАБАНЫ','slots-spin',!!s.spinning)}</div>`}
const SLOT_LINES=[[0,1,2],[3,4,5],[6,7,8],[0,4,8],[2,4,6]];
function spinSlots(){if(rt.slots?.spinning||!spend(state.stake))return;const epoch=roundEpoch;const stake=state.stake,s={spinning:true,cells:Array.from({length:9},()=>SYMS[rnd(6)]),stake,notice:''};rt.slots=s;render();let count=0;const tick=setInterval(()=>{if(epoch!==roundEpoch){clearInterval(tick);return}count++;s.cells=Array.from({length:9},()=>SYMS[rnd(6)]);for(let i=0;i<9;i++){const e=document.getElementById('slot'+i);if(e&&state.game==='slots')e.textContent=s.cells[i]}if(count>=17){clearInterval(tick);s.spinning=false;s.cells=Array.from({length:9},()=>SYMS[rnd(6)]);let payout=0,won=[];SLOT_LINES.forEach(line=>{const [a,b,c]=line;if(s.cells[a]===s.cells[b]&&s.cells[b]===s.cells[c]){payout+=stake/5*SLOT_MULT[s.cells[a]];won.push(...line)}});s.payout=Math.round(payout);s.wonIndices=won;s.notice=won.length?`Совпадение! Выплата: ${money(s.payout)}`:'Совпадений нет · попробуй снова';settle('Слоты',stake,s.payout,`${won.length/3} линий`);if(state.game==='slots')render()}},100)}
// Exact conditional survival probability of k safe cells among N squares with M bombs.
// Correct for all board sizes; explicitly cap rewards to protect integer wallet accounting.
const MINE_BOARDS=[16,25,32,36,49,64,100];
const mineDims=n=>n===32?[4,8]:[Math.sqrt(n),Math.sqrt(n)];
function mineMultiplier(s){const n=s.size||25,m=s.mineCount,k=s.opened.length;if(!Number.isInteger(n)||!MINE_BOARDS.includes(n)||!Number.isInteger(m)||m<1||m>=n||!Number.isInteger(k)||k<0||k>n-m)return 0;if(k===0)return 1;let product=.97;for(let i=0;i<k;i++)product*=(n-i)/(n-m-i);return product}
function minePayout(s){const m=mineMultiplier(s);return Math.min(BALANCE_CAP,Math.round(s.stake*m))}
function minesHTML(){const m=rt.mines;const active=!!m?.active;const size=m?.size||state.minesSize||25;const [rows,columns]=mineDims(size),opened=new Set(m?.opened||[]),mineSet=new Set(m?.mines||[]),revealed=!!m&&!active;const mult=m?.opened.length?mineMultiplier(m):1;const tiles=Array.from({length:size},(_,i)=>{const isOpen=opened.has(i),isMine=mineSet.has(i);return `<button class="mine-tile ${isOpen?'revealed':''} ${revealed&&isMine?'bomb':''} ${revealed&&!isMine&&isOpen?'safe':''}" data-action="mine-cell" data-index="${i}" ${!active||isOpen?'disabled':''} aria-label="Клетка ${i+1}">${isOpen?'◆':revealed&&isMine?'✹':'?'}</button>`}).join('');const boards=MINE_BOARDS.map(n=>`<button class="btn ${size===n?'active':''}" data-action="mine-size" data-value="${n}" ${active?'disabled':''}>${mineDims(n).join("×")} <b>${n} клеток</b></button>`).join('');const maxMines=Math.min(35,size-1);return `<div class="panel"><div class="panel-header"><h2>Минное поле ${rows} × ${columns}</h2><span class="status-pill ${active?'green':''}">${active?'РАУНД АКТИВЕН':'НОВЫЙ РАУНД'}</span></div><div class="panel-body"><div class="progress-row"><span>Безопасно открыто: <b>${m?.opened.length||0}</b></span><span>Множитель: <b class="accent">×${mult>=1e9?mult.toExponential(2):mult.toFixed(2)}</b></span></div><div class="mines-grid dynamic-mines" style="grid-template-columns:repeat(${columns},minmax(0,1fr))">${tiles}</div>${resultNote(m?.notice||'',m?.status==='cashed'?'win':m?.status==='lost'?'lose':'')}${active?`<button class="btn gold block" data-action="mines-cash" ${(m?.opened.length||0)===0?'disabled':''}>ЗАБРАТЬ ${money(minePayout(m))}</button>`:''}</div></div><div class="panel betting-panel"><div class="panel-header"><h3>Размер поля, мины и ставки</h3><span class="subcap">ВЕРОЯТНОСТЬ РАСТЁТ С РИСКОМ</span></div><div class="panel-body">${amountHTML()}<span class="panel-label">РАЗМЕР ПОЛЯ</span><div class="mines-size-options">${boards}</div><div style="display:flex;justify-content:space-between;margin-top:15px"><span class="panel-label">КОЛИЧЕСТВО МИН</span><b class="goldtext" id="minesCountValue">${m?.mineCount||state.minesCount}</b></div><input id="minesRange" type="range" min="1" max="${maxMines}" step="1" value="${m?.mineCount||state.minesCount}" ${active?'disabled':''}><p class="tiny">Шанс безопасно открыть первую клетку: ${((size-state.minesCount)/size*100).toFixed(2)}%. Максимальная выплата ограничена лимитом виртуального кошелька.</p><button class="btn primary block" style="margin-top:16px" data-action="mines-start" ${active?'disabled':''}>◆ ${active?'РАУНД ИДЁТ':'НАЧАТЬ ИГРУ'}</button></div></div>`}
function startMines(){if(rt.mines?.active)return;const size=state.minesSize||25,count=state.minesCount;if(!MINE_BOARDS.includes(size)||!Number.isInteger(count)||count<1||count>Math.min(35,size-1)||!spend(state.stake))return;const mines=new Set();while(mines.size<count)mines.add(rnd(size));rt.mines={mines:[...mines],size,mineCount:count,opened:[],stake:state.stake,active:true,status:'playing',notice:'Выбирай клетки. Чем больше мин, тем выше множитель!'};render()}
function openMine(index){const m=rt.mines;if(!m?.active||!Number.isInteger(index)||m.opened.includes(index)||index<0||index>=m.size)return;if(m.mines.includes(index)){m.active=false;m.status='lost';m.notice='Бум! Ты попал на мину';settle('Mines',m.stake,0,`${m.opened.length} клеток`)}else{m.opened.push(index);m.notice=`Открыто клеток: ${m.opened.length} · текущая выплата ${money(minePayout(m))}`;if(m.opened.length===m.size-m.mineCount){cashMines(true);return}}if(state.game==='mines')render()}
function cashMines(auto=false){const m=rt.mines;if(!m?.active||!m.opened.length)return;m.active=false;m.status='cashed';const payout=minePayout(m);m.notice=auto?'Все безопасные клетки открыты!':`Успешный вывод: ${money(payout)}`;settle('Mines',m.stake,payout,`${m.opened.length} клеток`);if(state.game==='mines')render()}
function plinkoHTML(){const p=rt.plinko||{};return `<div class="panel"><div class="panel-header"><h2>Доска Plinko</h2><span class="status-pill ${p.active?'green':''}">${p.active?'ШАР В ИГРЕ':'8 РЯДОВ'}</span></div><div class="panel-body"><canvas id="plinkoCanvas" class="plinko-stage" width="540" height="350" aria-label="Поле с штырьками и шарами"></canvas><div class="wheel-result" style="margin-top:13px">${p.result==null?'Шарик выбирает случайный путь':'×'+p.result}</div>${resultNote(p.notice||'',p.result>1?'win':'')}</div></div><div style="margin-top:17px">${betPanel(p.active?'ШАРИК ПАДАЕТ…':'∴ БРОСИТЬ ШАР','plinko-drop',!!p.active)}</div>`}
function drawPlinko(){const canvas=document.getElementById('plinkoCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;const w=540;ctx.clearRect(0,0,540,350);for(let r=0;r<8;r++){for(let i=0;i<=r;i++){const x=270+(i-r/2)*48,y=40+r*31;ctx.beginPath();ctx.arc(x,y,5.5,0,Math.PI*2);ctx.fillStyle='#7299af';ctx.shadowColor='#5bcddd';ctx.shadowBlur=9;ctx.fill();ctx.shadowBlur=0}}for(let i=0;i<9;i++){const x=270+(i-4)*48;ctx.fillStyle=PLINKO_PAY[i]>=3?'#bf6b3d':PLINKO_PAY[i]>=1?'#3d9291':'#5c657e';ctx.fillRect(x-22,288,44,48);ctx.fillStyle='white';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.fillText('×'+PLINKO_PAY[i],x,317)}if(rt.plinko?.active&&rt.plinko.path){const p=rt.plinko,t=Math.min(1,p.progress||0),seg=Math.min(7,Math.floor(t*8)),alpha=(t*8-seg);let x0=270,y0=8;let right=0;for(let k=0;k<seg;k++)right+=p.path[k];x0=270+(right-seg/2)*48;y0=8+seg*34;const nextX=270+(right+p.path[seg]-(seg+1)/2)*48,x=x0+(nextX-x0)*alpha,y=y0+alpha*34;ctx.beginPath();ctx.arc(x,y,11,0,Math.PI*2);ctx.fillStyle='#f3d47d';ctx.shadowColor='#f3d47d';ctx.shadowBlur=20;ctx.fill();ctx.shadowBlur=0}}
function dropPlinko(){if(rt.plinko?.active||!spend(state.stake))return;const epoch=roundEpoch;let p=rt.plinko||{};p.active=true;p.result=null;p.notice='';p.stake=state.stake;p.path=Array.from({length:8},()=>rnd(2));p.progress=0;rt.plinko=p;render();let start=performance.now();p.timer=setInterval(()=>{if(epoch!==roundEpoch){clearInterval(p.timer);return}p.progress=Math.min(1,(performance.now()-start)/2100);if(state.game==='plinko')drawPlinko();if(p.progress>=1){clearInterval(p.timer);p.active=false;const bucket=p.path.reduce((a,b)=>a+b,0);p.result=PLINKO_PAY[bucket];const payout=Math.round(p.stake*p.result);p.notice=`Карман ${bucket+1} · выплата ${money(payout)}`;settle('Plinko',p.stake,payout,`×${p.result}`);if(state.game==='plinko')render()}},33)}
function diceHTML(){const threshold=state.diceChance;const m=(97/threshold).toFixed(2);return `<div class="panel"><div class="panel-header"><h2>Dice 0–99</h2><span class="status-pill green">ТОЧНОЕ ЧИСЛО</span></div><div class="panel-body" style="text-align:center"><span class="panel-label">ПОСЛЕДНИЙ БРОСОК</span><div class="dice-number">${rt.diceRoll==null?'?':rt.diceRoll}</div><div class="dice-options"><button class="btn ${state.diceSide==='under'?'active':''}" data-action="dice-side" data-value="under">НИЖЕ ${threshold}</button><button class="btn ${state.diceSide==='over'?'active':''}" data-action="dice-side" data-value="over">ОТ ${100-threshold} И ВЫШЕ</button></div><input id="diceRange" type="range" min="5" max="95" step="1" value="${threshold}"><div class="dice-details"><div>Шанс выигрыша<b id="diceChanceValue">${threshold}%</b></div><div>Множитель<b class="accent" id="diceMultiplierValue">×${m}</b></div></div>${resultNote(rt.diceNotice,rt.diceNotice.startsWith('Выиграл')?'win':'')}</div></div><div style="margin-top:17px">${betPanel('⚄ БРОСИТЬ КОСТЬ','dice-roll')}</div>`}
function rollDice(){if(!spend(state.stake))return;const num=rnd(100),chance=state.diceChance,won=state.diceSide==='under'?num<chance:num>=100-chance,payout=won?Math.round(state.stake*(.97*100/chance)):0;rt.diceRoll=num;rt.diceNotice=won?`Выиграл! Выплата ${money(payout)}`:`Выпало ${num} · ставка проиграла`;settle('Dice',state.stake,payout,`Бросок ${num}`);render()}
function bacValue(cards){return cards.reduce((a,c)=>a+(cardVal(c)%10),0)%10}
function baccaratDraw(){const deck=newDeck(8),player=[draw(deck),draw(deck)],banker=[draw(deck),draw(deck)];let p=bacValue(player),b=bacValue(banker);if(p<8&&b<8){let p3=null;if(p<=5){p3=draw(deck);player.push(p3)}if(p3===null){if(b<=5)banker.push(draw(deck))}else{const v=cardVal(p3)%10;let take=b<=2||(b===3&&v!==8)||(b===4&&v>=2&&v<=7)||(b===5&&v>=4&&v<=7)||(b===6&&(v===6||v===7));if(take)banker.push(draw(deck))}}p=bacValue(player);b=bacValue(banker);return {player,banker,p,b,winner:p>b?'player':p<b?'banker':'tie'}}
function baccaratHTML(){const b=rt.baccarat||{};let opts=[['player','ИГРОК ×2'],['banker','БАНКИР ×1,95'],['tie','НИЧЬЯ ×9']];let dealerHand=b.banker||[{rank:'A',suit:'♠'},{rank:'K',suit:'♣'}],playerHand=b.player||[{rank:'Q',suit:'♥'},{rank:'7',suit:'♦'}];return `<div class="card-felt"><div class="table-sign">PUNTO BANCO • BACCARAT</div><div class="baccarat-set"><div class="baccarat-position"><h3>ИГРОК ${b.player? '· '+b.p+' очков':''}</h3><div class="hand">${playerHand.map(c=>cardHTML(c,!b.player)).join('')}</div></div><div class="baccarat-position"><h3>БАНКИР ${b.banker?'· '+b.b+' очков':''}</h3><div class="hand">${dealerHand.map(c=>cardHTML(c,!b.banker)).join('')}</div></div></div><div class="center-message">${esc(b.notice||'Выбери исход и сдавай карты')}</div><div class="baccarat-options">${opts.map(([val,label])=>`<button class="btn small ${state.baccaratBet===val?'active':''}" data-action="baccarat-pick" data-value="${val}">${label}</button>`).join('')}</div><div class="table-buttons"><button class="btn primary" data-action="baccarat-play">♣ СДАТЬ КАРТЫ</button></div></div><div class="panel betting-panel"><div class="panel-header"><h3>Ставка на исход</h3></div><div class="panel-body">${amountHTML()}<p class="tiny">Банкир: комиссия 5% с выигрыша. Ставка на игрока или банкира при ничьей возвращается.</p></div></div>`}
function playBaccarat(){if(!spend(state.stake))return;const stake=state.stake,result=baccaratDraw(),pick=state.baccaratBet,won=pick===result.winner;let payout=won?Math.round(stake*(pick==='tie'?9:pick==='banker'?1.95:2)):result.winner==='tie'&&pick!=='tie'?stake:0;result.notice=won?`УГАДАЛ! +${money(payout-stake)}`:payout===stake?'Ничья · ставка возвращена':`Победил ${result.winner==='player'?'игрок':result.winner==='banker'?'банкир':'ничейный исход'}`;rt.baccarat=result;settle('Баккара',stake,payout,result.winner);render()}
function coinHTML(){const c=rt.coin||{side:null};return `<div class="panel"><div class="panel-header"><h2>Один бросок · один исход</h2><span class="status-pill green">50 / 50</span></div><div class="panel-body"><div class="coin-stage"><div id="coinDisk" class="coin ${c.flipping?'flipping':''}">${c.side==null?'✦':c.side==='heads'?'★':'❖'}</div></div><div class="center-message" style="text-align:center">${c.flipping?'Подбрасываем…':c.side==null?'Орел или решка?':c.side==='heads'?'ОРЁЛ':'РЕШКА'}</div><div class="coin-options"><button class="btn ${state.coinBet==='heads'?'active':''}" data-action="coin-pick" data-value="heads">★ ОРЁЛ</button><button class="btn ${state.coinBet==='tails'?'active':''}" data-action="coin-pick" data-value="tails">❖ РЕШКА</button></div>${resultNote(c.notice||'',c.payout>c.stake?'win':'')}</div></div><div style="margin-top:17px">${betPanel(c.flipping?'ПОДБРАСЫВАЕМ…':'◐ ПОДБРОСИТЬ','coin-flip',!!c.flipping)}</div>`}
function flipCoin(){if(rt.coin?.flipping||!spend(state.stake))return;const epoch=roundEpoch,pick=state.coinBet;const stake=state.stake,side=rnd(2)?'heads':'tails',c={flipping:true,side:null,notice:'',stake};rt.coin=c;render();setTimeout(()=>{if(epoch!==roundEpoch)return;c.flipping=false;c.side=side;c.payout=side===pick?Math.round(stake*1.95):0;c.notice=c.payout?'Угадал! Выигрыш '+money(c.payout):'Не угадал · ещё попытка?';settle('Монетка',stake,c.payout,side==='heads'?'Орёл':'Решка');if(state.game==='coin')render()},1200)}

// Keno: choose 5 distinct numbers; draw 10 from 40 without replacement.
const KENO_PAY=[0,0,2,2.5,12,200];
function kenoHTML(){const selected=new Set(state.kenoPicks);const drawn=rt.keno?.drawn||[];const results=new Set(drawn);const cells=Array.from({length:40},(_,i)=>{const n=i+1;return `<button class="keno-num ${selected.has(n)?'selected':''} ${results.has(n)?'drawn':''} ${selected.has(n)&&results.has(n)?'matched':''}" data-action="keno-pick" data-value="${n}" aria-pressed="${selected.has(n)}">${n}</button>`}).join('');return `<div class="panel"><div class="panel-header"><h2>Кено · 5 из 40</h2><span class="status-pill green">10 ШАРОВ</span></div><div class="panel-body"><p class="tiny">Отметь 5 чисел. Выигрыш зависит от совпадений.</p><div class="keno-board">${cells}</div><div class="keno-count">Выбрано: <b>${selected.size} / 5</b> ${rt.keno?`· Совпало: <b>${rt.keno.hits}</b>`:''}</div><div class="keno-paytable">${KENO_PAY.map((v,i)=>`<span>${i} совп. <b>×${v}</b></span>`).join('')}</div>${resultNote(rt.keno?.notice||'',rt.keno?.payout>rt.keno?.stake?'win':'')}</div></div><div style="margin-top:17px">${betPanel('✳ РАЗЫГРАТЬ 10 ЧИСЕЛ','keno-play',selected.size!==5)}</div>`}
function kenoPick(n){if(!Number.isInteger(n)||n<1||n>40)return;let items=state.kenoPicks;const i=items.indexOf(n);if(i>=0)items.splice(i,1);else if(items.length<5)items.push(n);else return;rt.keno=null;render()}
function playKeno(){if(state.kenoPicks.length!==5||new Set(state.kenoPicks).size!==5||!spend(state.stake))return;const available=Array.from({length:40},(_,i)=>i+1),drawn=[];for(let i=0;i<10;i++){const j=i+rnd(40-i);[available[i],available[j]]=[available[j],available[i]];drawn.push(available[i])}const hits=drawn.filter(n=>state.kenoPicks.includes(n)).length,stake=state.stake,payout=Math.round(stake*KENO_PAY[hits]);rt.keno={drawn,hits,stake,payout,notice:`Выпало: ${drawn.join(', ')}. Совпадений: ${hits}. Выплата: ${money(payout)}`};settle('Кено',stake,payout,`${hits}/5`);render()}
// Video poker: a single standard 52-card deck, one redraw, no jokers.
const POKER_PAY={royal:250,straightFlush:50,quads:25,fullHouse:9,flush:6,straight:4,trips:3,twoPair:2,jacks:1,none:0};
function evaluatePoker(cards){if(!Array.isArray(cards)||cards.length!==5)return {kind:'none',name:'Нет комбинации',mult:0};const ranks=cards.map(c=>RANKS.indexOf(c.rank)+1);if(ranks.some(x=>x<1))return {kind:'none',name:'Нет комбинации',mult:0};const values=ranks.map(x=>x===1?14:x).sort((a,b)=>a-b),unique=[...new Set(values)],flush=cards.every(c=>c.suit===cards[0].suit);const straight=(unique.length===5&&(values[4]-values[0]===4||unique.join(',')==='2,3,4,5,14'));const freq={};values.forEach(v=>freq[v]=(freq[v]||0)+1);const counts=Object.values(freq).sort((a,b)=>b-a);let kind='none',name='Нет комбинации';if(straight&&flush&&values.join(',')==='10,11,12,13,14'){kind='royal';name='РОЯЛ-ФЛЕШ'}else if(straight&&flush){kind='straightFlush';name='Стрит-флеш'}else if(counts[0]===4){kind='quads';name='Каре'}else if(counts[0]===3&&counts[1]===2){kind='fullHouse';name='Фулл-хаус'}else if(flush){kind='flush';name='Флеш'}else if(straight){kind='straight';name='Стрит'}else if(counts[0]===3){kind='trips';name='Тройка'}else if(counts[0]===2&&counts[1]===2){kind='twoPair';name='Две пары'}else if(counts[0]===2&&Object.entries(freq).some(([rank,n])=>n===2&&Number(rank)>=11)){kind='jacks';name='Пара валетов или старше'}return {kind,name,mult:POKER_PAY[kind]}}
function pokerHTML(){const p=rt.poker||{phase:'idle',cards:[]};const playing=p.phase==='hold';const cards=p.cards.length?p.cards:Array.from({length:5},(_,i)=>({rank:'?',suit:'♠'}));return `<div class="panel"><div class="panel-header"><h2>Jacks or Better</h2><span class="status-pill ${playing?'green':''}">${playing?'ВЫБЕРИ КАРТЫ':'ВИДЕОПОКЕР'}</span></div><div class="panel-body"><div class="poker-table"><div class="poker-cards">${cards.map((c,i)=>`<button class="poker-card ${playing&&p.held.includes(i)?'held':''}" data-action="poker-hold" data-index="${i}" ${!playing?'disabled':''} aria-pressed="${playing&&p.held.includes(i)}">${cardHTML(c,!p.cards.length)}<span class="hold-tag">${playing?(p.held.includes(i)?'ОСТАВИТЬ':'МЕНЯТЬ'):'♠'}</span></button>`).join('')}</div><div class="center-message">${esc(p.notice||'Раздай 5 карт и собери выигрышную комбинацию')}</div></div><div class="poker-pays">${[['Пара J+',1],['Две пары',2],['Тройка',3],['Стрит',4],['Флеш',6],['Фулл-хаус',9],['Каре',25],['Стрит-флеш',50],['Роял-флеш',250]].map(([name,x])=>`<span>${name} <b>×${x}</b></span>`).join('')}</div></div></div><div style="margin-top:17px">${betPanel(playing?'⇄ ЗАМЕНИТЬ КАРТЫ':'♥ РАЗДАТЬ 5 КАРТ',playing?'poker-draw':'poker-deal')}</div>`}
function pokerDeal(){if(rt.poker?.phase==='hold'||!spend(state.stake))return;const deck=newDeck(1),cards=Array.from({length:5},()=>draw(deck));rt.poker={phase:'hold',deck,cards,held:[],stake:state.stake,notice:'Нажми на карты, которые хочешь оставить, затем замени остальные'};render()}
function pokerHold(i){const p=rt.poker;if(p?.phase!=='hold'||!Number.isInteger(i)||i<0||i>4)return;const j=p.held.indexOf(i);if(j>=0)p.held.splice(j,1);else p.held.push(i);render()}
function pokerDraw(){const p=rt.poker;if(p?.phase!=='hold')return;for(let i=0;i<5;i++)if(!p.held.includes(i))p.cards[i]=draw(p.deck);const result=evaluatePoker(p.cards);p.phase='done';p.result=result;p.payout=p.stake*result.mult;p.notice=`${result.name} · выплата ${money(p.payout)}`;settle('Видеопокер',p.stake,p.payout,result.name);render()}
// SIC BO — three honest independent dice, no reroll tricks.
const SICBO_SUM_PAY={4:51,5:19,6:15,7:13,8:9,9:7,10:7,11:7,12:7,13:9,14:13,15:15,16:19,17:51};
const SICBO_OPTIONS=[
 [['small','МАЛОЕ 4–10','×2'],['big','БОЛЬШОЕ 11–17','×2'],['triple','ЛЮБАЯ ТРОЙКА','×25']],
 Array.from({length:14},(_,i)=>['sum-'+(i+4),'СУММА '+(i+4),'×'+SICBO_SUM_PAY[i+4]]),
 Array.from({length:6},(_,i)=>['exact-'+(i+1),'ТОЧНАЯ ТРОЙКА '+(i+1),'×181']),
 Array.from({length:6},(_,i)=>['pair-'+(i+1),'ПАРА '+(i+1),'×12']),
 Array.from({length:6},(_,i)=>['single-'+(i+1),'ЧИСЛО '+(i+1),'×2–×4'])
];
const SICBO_IDS=new Set(SICBO_OPTIONS.flat().map(x=>x[0]));
function sicboHTML(){const r=rt.sicbo;const categories=['КРУПНЫЕ СТАВКИ','ТОЧНАЯ СУММА','ТОЧНЫЕ ТРОЙКИ','ДВА ОДИНАКОВЫХ','ОДНО ЧИСЛО'];const sections=SICBO_OPTIONS.map((arr,i)=>`<div class="panel-label" style="margin-top:19px">${categories[i]}</div><div class="option-grid">${arr.map(([id,title,m])=>`<button class="btn ${state.sicboBet===id?'active':''}" data-action="sicbo-pick" data-value="${id}">${title}<br><b>${m}</b></button>`).join('')}</div>`).join('');return `<div class="panel"><div class="panel-header"><h2>⚂ SIC BO</h2><span class="status-pill green">35 ВАРИАНТОВ СТАВОК</span></div><div class="panel-body"><div class="dice-three">${(r?.dice||[1,3,6]).map(v=>`<span class="die-face" aria-label="На кубике ${v}">${['','⚀','⚁','⚂','⚃','⚄','⚅'][v]}</span>`).join('')}</div><div class="wheel-result">${r?'Сумма: '+r.sum:'СДЕЛАЙ СТАВКУ'}</div>${sections}${resultNote(r?.notice||'',r?.payout>r?.stake?'win':r?'lose':'')}</div></div><div style="margin-top:17px">${betPanel('⚂ БРОСИТЬ ТРИ КУБИКА','sicbo-roll')}</div>`}
function sicboOutcome(dice,pick){if(!Array.isArray(dice)||dice.length!==3||dice.some(v=>!Number.isInteger(v)||v<1||v>6))throw Error('Некорректные кубики');const sum=dice.reduce((a,b)=>a+b,0),triple=dice.every(x=>x===dice[0]);return pick==='triple'?triple:!triple&&(pick==='small'?sum>=4&&sum<=10:pick==='big'&&sum>=11&&sum<=17)}
function sicboMultiplier(dice,pick){if(!Array.isArray(dice)||dice.length!==3||dice.some(v=>!Number.isInteger(v)||v<1||v>6)||!SICBO_IDS.has(pick))throw Error('Некорректная ставка');if(['small','big','triple'].includes(pick))return sicboOutcome(dice,pick)?(pick==='triple'?25:2):0;const [category,nText]=pick.split('-'),n=Number(nText),sum=dice.reduce((a,b)=>a+b,0),same=dice.filter(v=>v===n).length;if(category==='sum')return sum===n?SICBO_SUM_PAY[n]:0;if(category==='exact')return same===3?181:0;if(category==='pair')return same>=2?12:0;if(category==='single')return [0,2,3,4][same]||0;return 0}
function playSicbo(){const stake=state.stake,pick=state.sicboBet;if(!SICBO_IDS.has(pick)||!spend(stake))return;const dice=Array.from({length:3},()=>rnd(6)+1),sum=dice.reduce((a,b)=>a+b,0),m=sicboMultiplier(dice,pick),payout=extraPayout(stake,m);rt.sicbo={dice,sum,stake,payout,notice:m?`Победа! Выплата ${money(payout)}`:'Ставка не сыграла'};settle('Sic Bo',stake,payout,dice.join('-'));render()}
// LIMBO — P(reach target M) = 0.97 / M for every selected target.
function limboHTML(){const x=state.limboTarget,r=rt.limbo;return `<div class="panel"><div class="panel-header"><h2>⇡ LIMBO</h2><span class="status-pill green">97% RTP</span></div><div class="panel-body" style="text-align:center"><div class="center-message">Цель — попасть не ниже выбранного коэффициента</div><div class="limbo-number">${r?'×'+r.actual.toFixed(2):'×—'}</div><div class="dice-details"><div>ТВОЯ ЦЕЛЬ<b>×${x}</b></div><div>ВЕРОЯТНОСТЬ<b class="accent">${(97/x).toFixed(2)}%</b></div></div><div class="option-grid">${[1.5,2,3,5,10,20,50,100].map(m=>`<button class="btn ${x===m?'active':''}" data-action="limbo-target" data-value="${m}">×${m}</button>`).join('')}</div>${resultNote(r?.notice||'',r?.won?'win':r?'lose':'')}</div></div><div style="margin-top:17px">${betPanel('⇡ ИСПЫТАТЬ УДАЧУ','limbo-play')}</div>`}
function limboOutcome(target,u){if(!(target>1)||!(u>=0&&u<1))throw Error('Некорректная цель');return .97/(1-u)>=target}
function playLimbo(){const stake=state.stake,target=state.limboTarget;if(!spend(stake))return;const u=unit(),actual=Math.min(100000,.97/(1-u)),won=limboOutcome(target,u),payout=won?Math.round(stake*target):0;rt.limbo={actual,stake,target,won,payout,notice:won?`Выплата: ${money(payout)}`:`Не удалось достичь ×${target}`};settle('Limbo',stake,payout,`Цель ×${target}`);render()}
// HI-LO — independent, uniform next rank; ties return the stake. A is low.
function hiloCard(){return {rank:RANKS[rnd(13)],suit:SUITS[rnd(4)]}}
function hiloOdds(rank,side){const n=RANKS.indexOf(rank)+1;if(n<1)return 0;const winning=side==='higher'?13-n:side==='lower'?n-1:0;return winning>0?(.97*12/winning):0}
function hiloHTML(){if(!rt.hilo)rt.hilo={current:hiloCard(),previous:null};const r=rt.hilo,rank=RANKS.indexOf(r.current.rank)+1;const options=[['higher','ВЫШЕ',rank<13],['lower','НИЖЕ',rank>1]];return `<div class="panel"><div class="panel-header"><h2>⇵ Выше / ниже</h2><span class="status-pill green">ТУЗ = 1</span></div><div class="panel-body"><div class="hilo-cards"><div><span class="panel-label">ТЕКУЩАЯ КАРТА</span>${cardHTML(r.current)}</div><div class="hilo-arrow">→</div><div><span class="panel-label">ПРОШЛЫЙ РЕЗУЛЬТАТ</span>${r.previous?cardHTML(r.previous):cardHTML({rank:'?',suit:'♠'},true)}</div></div><div class="option-grid">${options.map(([id,title,enabled])=>`<button class="btn ${state.hiloBet===id?'active':''}" data-action="hilo-side" data-value="${id}" ${!enabled?'disabled':''}>${title} <b>×${hiloOdds(r.current.rank,id).toFixed(2)}</b></button>`).join('')}</div><p class="tiny">Равный ранг: возврат ставки. Следующая карта становится текущей.</p>${resultNote(r.notice||'',r.payout>r.stake?'win':r.notice&&r.payout===0?'lose':'')}</div></div><div style="margin-top:17px">${betPanel('⇵ ОТКРЫТЬ КАРТУ','hilo-play',hiloOdds(r.current.rank,state.hiloBet)===0)}</div>`}
function playHilo(){if(!rt.hilo)rt.hilo={current:hiloCard()};const r=rt.hilo,mult=hiloOdds(r.current.rank,state.hiloBet);if(!mult)return;const stake=state.stake;if(!spend(stake))return;const next=hiloCard(),a=RANKS.indexOf(r.current.rank),b=RANKS.indexOf(next.rank),tie=a===b,won=!tie&&(state.hiloBet==='higher'?b>a:b<a),payout=tie?stake:won?Math.round(stake*mult):0;r.previous=r.current;r.current=next;r.stake=stake;r.payout=payout;r.notice=tie?'Одинаковый ранг — ставка возвращена':won?`Угадал! Выплата ${money(payout)}`:'Не угадал';if(hiloOdds(r.current.rank,state.hiloBet)===0)state.hiloBet=state.hiloBet==='higher'?'lower':'higher';settle('Выше / ниже',stake,payout,r.notice);render()}
// CRAPS — standard Pass Line: single wager held through multiple throws.
function crapsStep(point,sum){if(!Number.isInteger(sum)||sum<2||sum>12)throw Error('Некорректная сумма');if(point===null){if(sum===7||sum===11)return {status:'won',point:null};if([2,3,12].includes(sum))return {status:'lost',point:null};return {status:'point',point:sum}}if(sum===point)return {status:'won',point};if(sum===7)return {status:'lost',point};return {status:'point',point}}
function crapsDontStep(point,sum){if(point===null){if(sum===2||sum===3)return {status:'won',point:null};if(sum===12)return {status:'push',point:null};if(sum===7||sum===11)return {status:'lost',point:null};return {status:'point',point:sum}}if(sum===7)return {status:'won',point};if(sum===point)return {status:'lost',point};return {status:'point',point}}
function crapsHTML(){const c=rt.craps||{},active=!!c.active;const dont=(c.bet||state.crapsBet)==='dont';return `<div class="panel"><div class="panel-header"><h2>⚅ CRAPS · ${dont?"DON’T PASS":"PASS LINE"}</h2><span class="status-pill ${active?'green':''}">${active?'ПОЙНТ АКТИВЕН':'ПЕРВЫЙ БРОСОК'}</span></div><div class="panel-body" style="text-align:center"><div class="dice-three">${(c.dice||[3,4]).map(v=>`<span class="die-face">${['','⚀','⚁','⚂','⚃','⚄','⚅'][v]}</span>`).join('')}</div><div class="wheel-result">${c.point?'ПОЙНТ '+c.point:c.sum?'ВЫПАЛО '+c.sum:(dont?'СТАВКА DON’T PASS':'СТАВКА PASS LINE')}</div><div class="center-message">${esc(c.notice||(dont?'Don’t Pass: 2/3 — победа, 7/11 — проигрыш, 12 — возврат. После пойнта победа на 7.':'Pass Line: 7/11 — победа, 2/3/12 — проигрыш. После пойнта победа на выбранное число.'))}</div><div class="craps-hint">${active?(dont?'Семёрка раньше '+c.point+' = победа ×2. Ставка удерживается до исхода.':'Сумма '+c.point+' раньше 7 = победа ×2. Ставка удерживается до исхода.'):'Новый раунд: ставка ×2 при победе'}</div></div></div><div style="margin-top:17px">${active?`<div class="panel"><div class="panel-body"><b>На кону: ${money(c.stake)}</b><button class="btn primary block" style="margin-top:16px" data-action="craps-roll">⚅ БРОСИТЬ ЕЩЁ РАЗ</button></div></div>`:betPanel('⚅ СДЕЛАТЬ СТАВКУ И БРОСИТЬ','craps-roll',false,extraOptions([['pass','PASS LINE','7/11 — выигрыш'],['dont','DON’T PASS','2/3 — выигрыш']],'craps-pick',state.crapsBet||'pass'))}</div>`}
