function threeScore(cards){if(cards.length!==3||cards.some(c=>!RANKS.includes(c.rank)))throw Error('Карты');const vals=cards.map(c=>RANKS.indexOf(c.rank)===0?14:RANKS.indexOf(c.rank)+1).sort((a,b)=>b-a),asc=[...vals].sort((a,b)=>a-b),flush=cards.every(c=>c.suit===cards[0].suit),straight=(asc[2]-asc[0]===2&&new Set(asc).size===3)||asc.join(',')==='2,3,14';const tri=vals[0]===vals[1]&&vals[1]===vals[2],pair=vals[0]===vals[1]||vals[1]===vals[2];let cls=flush&&straight?5:tri?4:straight?3:flush?2:pair?1:0;let tie=vals;if(pair&&!tri){const p=vals.find(v=>vals.filter(x=>x===v).length===2),k=vals.find(v=>v!==p);tie=[p,k]}if(straight&&asc.join(',')==='2,3,14')tie=[3];return {cls,tie,qualifies:cls>0||vals[0]>=12}}
