function bingo90Ticket(){for(let trial=0;trial<100;trial++){const occupancy=Array.from({length:3},()=>Array(9).fill(false)),remain=[5,5,5];for(let col=0;col<9;col++){const row=rnd(3);occupancy[row][col]=true;remain[row]--}let valid=true;while(remain.some(x=>x>0)){const opts=[];for(let r=0;r<3;r++)if(remain[r]>0)for(let c=0;c<9;c++)if(!occupancy[r][c])opts.push([r,c]);if(!opts.length){valid=false;break}const [r,c]=opts[rnd(opts.length)];occupancy[r][c]=true;remain[r]--}if(!valid||remain.some(x=>x!==0))continue;const board=occupancy.map(x=>x.map(y=>y?0:null));for(let col=0;col<9;col++){const start=col===0?1:col*10,end=col===8?90:col*10+9,used=[],rows=[];for(let row=0;row<3;row++)if(occupancy[row][col])rows.push(row);const pool=Array.from({length:end-start+1},(_,i)=>start+i);for(const row of rows)used.push(pool.splice(rnd(pool.length),1)[0]);used.sort((a,b)=>a-b).forEach((num,i)=>board[rows[i]][col]=num)}return board}throw Error('Не удалось создать билет')}
