const V17_RULES={
 caribbean:'Caribbean Stud: ставь Ante, затем изучи пять карт и открытую карту дилера. Fold теряет Ante. Call требует дополнительно 2× Ante. Дилер квалифицируется с A-K-high или лучше; иначе Ante выигрывает 1:1, Call возвращается. При победе Ante 1:1, Call по таблице: старшая карта/пара 1:1, две пары 2:1, тройка 3:1, стрит 4:1, флеш 5:1, фулл-хаус 7:1, каре 20:1, стрит-флеш 50:1, роял-флеш 100:1. Максимальный Ante 500 000 фишек.',
 teenpatti:'Teen Patti: Ante, по желанию дополнительная Pair Plus (в размере Ante). После трёх карт выбери Fold или Play (дополнительная ставка 1× Ante). Дилер квалифицируется с дамой или сильнее. В противном случае Ante выигрывает 1:1, Play возвращается. При квалификации победа оплачивается 1:1 по каждой ставке, ничья — возврат. Ante Bonus за стрит (1:1), тройку (4:1), стрит-флеш (5:1) начисляется при Play. Pair Plus оплачивается независимо от Fold по таблице.',
 fantan:'Fan Tan: из кучки отсчитывают по четыре, результат 1–4 равновероятен. Fan: одно число, выигрыш 2,85:1. Kwok: два соседних числа, 0,95:1. Nim: одно выигрышное число (1,9:1) и одно число возврата ставки. Тройной охват: три числа (19:60 к 1). Все коэффициенты после условной комиссии 5%.',
 crown:'Crown & Anchor: три независимых кубика имеют по шесть равновероятных символов. Выбери один символ. Если он появился один раз — выигрыш 1:1, два — 2:1, три — 3:1; во всех случаях возвращается исходная ставка. Если совпадений нет, ставка проиграна.'
};
Object.assign(MORE_RULES,V17_RULES);
const V17_RUNTIME={caribbean:null,teenpatti:null,fantan:null,crown:null};
Object.assign(rt,V17_RUNTIME);
const v17Reset=resetRuntime;
resetRuntime=function(){v17Reset();Object.assign(rt,V17_RUNTIME)};
Object.assign(state,{teenPairPlus:false,fantanBet:'fan:1',crownBet:0});

function qualifiedCaribbean(cards){const score=pokerFiveScore(cards);return score[0]>0||(score[0]===0&&score[1]===14&&score[2]===13)}
function caribbeanCallOdds(cards){const score=pokerFiveScore(cards);return score[0]===8?(score[1]===14?100:50):({7:20,6:7,5:5,4:4,3:3,2:2,1:1,0:1}[score[0]]||1)}
function caribbeanPayment(ante,player,dealer){const p=pokerFiveScore(player),d=pokerFiveScore(dealer),cmp=comparePokerScores(p,d),call=2*ante;if(!qualifiedCaribbean(dealer))return {payout:4*ante,reason:'Дилер не квалифицировался · Ante 1:1, Call возвращена'};if(cmp<0)return {payout:0,reason:'Дилер победил'};if(cmp===0)return{payout:3*ante,reason:'Ничья · возврат ставок'};const odds=caribbeanCallOdds(player);return {payout:2*ante+(1+odds)*call,reason:`Победа! Ante 1:1, Call ${odds}:1`}}
function caribbeanHTML(){const r=rt.caribbean,active=!!r?.active;const cards=r?.player||[];return `<div class="panel"><div class="panel-header"><h2>♠ CARIBBEAN STUD</h2><span class="status-pill green">ANTE / CALL ×2</span></div><div class="panel-body"><span class="panel-label">ТВОИ ПЯТЬ КАРТ</span><div class="poker-cards">${cards.length?cards.map(c=>cardHTML(c)).join(''):'<span class="center-message">Раздача пяти карт</span>'}</div><span class="panel-label">ДИЛЕР ${active?'· ОДНА КАРТА ОТКРЫТА':''}</span><div class="poker-cards">${r?(active?r.dealer.map((c,i)=>cardHTML(c,i!==0)).join(''):r.dealer.map(c=>cardHTML(c)).join('')):'<span class="center-message">?</span>'}</div>${resultNote(r?.notice||'Ante → открой карты → Call или Fold',r?.payout>r?.stake?'win':'')}</div></div><div style="margin-top:16px">${active?`<div class="panel"><div class="panel-body"><p class="tiny">Call стоит ${money(2*r.stake)} дополнительных фишек. Можно отказаться и потерять только Ante.</p><div class="button-row"><button class="btn primary" data-action="caribbean-call">CALL ×2</button><button class="btn ghost" data-action="caribbean-fold">FOLD</button></div></div></div>`:betPanel('РАЗДАТЬ 5 КАРТ','caribbean-start')}</div>`}
function caribbeanStart(){if(rt.caribbean?.active)return;const stake=state.stake;if(stake>500000){toast('Максимум Ante — 500 000',true);return}if(!spend(stake))return;const deck=newDeck(1),player=Array.from({length:5},()=>draw(deck)),dealer=Array.from({length:5},()=>draw(deck));rt.caribbean={active:true,stake,player,dealer,notice:'Посмотри на карты и выбери Call или Fold'};render()}
function caribbeanFinish(call){const r=rt.caribbean;if(!r?.active)return;if(!call){r.active=false;r.payout=0;r.notice='Fold: Ante проиграна';settle('Caribbean Stud',r.stake,0,'Fold');render();return}if(!spend(2*r.stake))return;const outcome=caribbeanPayment(r.stake,r.player,r.dealer);r.active=false;r.payout=Math.min(BALANCE_CAP,Math.round(outcome.payout));r.notice=outcome.reason;settle('Caribbean Stud',3*r.stake,r.payout,outcome.reason);render()}

// Three-card Teen Patti ranking: mini-royal > three-of-kind > straight flush > straight > flush > pair > high.
function teenScore(cards){if(cards.length!==3)throw Error('Three cards required');const ranks=cards.map(c=>c.rank==='A'?14:RANKS.indexOf(c.rank)+1).sort((a,b)=>b-a);const freq=new Map();ranks.forEach(n=>freq.set(n,(freq.get(n)||0)+1));const groups=[...freq.entries()].sort((a,b)=>b[1]-a[1]||b[0]-a[0]);const flush=cards.every(c=>c.suit===cards[0].suit);const unique=[...new Set(ranks)];const straight=unique.length===3&&(ranks[0]-ranks[2]===2||ranks.join(',')==='14,3,2');const top=straight?(ranks[0]===14&&ranks[1]===3?3:ranks[0]):0;const royal=flush&&ranks.join(',')==='14,13,12';if(royal)return[7,14];if(groups[0][1]===3)return[6,groups[0][0]];if(straight&&flush)return[5,top];if(straight)return[4,top];if(flush)return[3,...ranks];if(groups[0][1]===2)return[2,groups[0][0],groups[1][0]];return[1,...ranks]}
function teenPairPlusProfit(score){return {7:100,6:30,5:40,4:5,3:4,2:1}[score[0]]||0}
function teenAnteBonus(score){return score[0]===7||score[0]===5?5:score[0]===6?4:score[0]===4?1:0}
function teenPayment(ante,player,dealer,pairPlus){const p=teenScore(player),d=teenScore(dealer),cmp=comparePokerScores(p,d),qualifies=d[0]>1||d[1]>=12;const pairPay=pairPlus?(teenPairPlusProfit(p)+ (teenPairPlusProfit(p)>0?1:0))*ante:0;let base,reason;if(!qualifies){base=3*ante;reason='Дилер не квалифицировался · Ante выиграла, Play возвращена'}else if(cmp>0){base=4*ante;reason='Победа над дилером'}else if(cmp===0){base=2*ante;reason='Ничья · ставки возвращены'}else{base=0;reason='Дилер победил'}const bonus=teenAnteBonus(p)*ante;return{payout:base+bonus+pairPay,reason:reason+(bonus?` · Ante Bonus +${money(bonus)}`:'')+(pairPlus?` · Pair Plus: ${money(pairPay)}`:''),qualifies}}
function teenHTML(){const r=rt.teenpatti,active=!!r?.active;return `<div class="panel"><div class="panel-header"><h2>🂡 TEEN PATTI</h2><span class="status-pill green">ANTE + PLAY</span></div><div class="panel-body"><span class="panel-label">ТВОЯ РУКА</span><div class="poker-cards">${r?r.player.map(c=>cardHTML(c)).join(''):'Три карты'}</div><span class="panel-label">ДИЛЕР</span><div class="poker-cards">${r?r.dealer.map(c=>cardHTML(c,active)).join(''):'Три закрытые карты'}</div>${resultNote(r?.notice||'За один Ante раздаётся три карты. Опционально Pair Plus.',r?.payout>r?.stake?'win':'')}</div></div><div style="margin-top:16px">${active?`<div class="panel"><div class="panel-body"><p class="tiny">Play — дополнительная ставка ${money(r.stake)}. Fold теряет Ante, но бонус Pair Plus остаётся.</p><div class="button-row"><button class="btn primary" data-action="teen-play">PLAY ×1</button><button class="btn ghost" data-action="teen-fold">FOLD</button></div></div></div>`:betPanel('РАЗДАТЬ КАРТЫ','teen-start',false,`<button class="mode-choice ${state.teenPairPlus?'active':''}" type="button" data-action="teen-pair" aria-pressed="${state.teenPairPlus}">✦ Pair Plus: ${state.teenPairPlus?'ВКЛ':'ВЫКЛ'} (ещё 1× Ante)</button>`)}</div>`}
function teenStart(){if(rt.teenpatti?.active)return;const s=state.stake,extra=state.teenPairPlus;if(extra&&state.balance<2*s){toast('Для Ante + Pair Plus не хватает фишек',true);return}if(!spend(s))return;if(extra&&!spend(s)){refund(s);return}const deck=newDeck(1),player=Array.from({length:3},()=>draw(deck)),dealer=Array.from({length:3},()=>draw(deck));rt.teenpatti={active:true,stake:s,pairPlus:extra,player,dealer,notice:'Выбери Play или Fold'};render()}
function teenFinish(play){const r=rt.teenpatti;if(!r?.active)return;const pairPay=r.pairPlus?(teenPairPlusProfit(teenScore(r.player))+(teenPairPlusProfit(teenScore(r.player))>0?1:0))*r.stake:0;if(!play){r.active=false;r.payout=pairPay;r.notice='Fold: Ante проиграна'+(r.pairPlus?` · Pair Plus ${money(pairPay)}`:'');settle('Teen Patti',r.stake*(1+Number(r.pairPlus)),pairPay,'Fold');render();return}if(!spend(r.stake))return;const outcome=teenPayment(r.stake,r.player,r.dealer,r.pairPlus);r.active=false;r.payout=Math.min(BALANCE_CAP,Math.round(outcome.payout));r.notice=outcome.reason;settle('Teen Patti',r.stake*(2+Number(r.pairPlus)),r.payout,r.notice);render()}

// Fan Tan: remainder of beads when counted in fours (1..4); no external RNG.
const FAN_BETS=[...Array.from({length:4},(_,i)=>[`fan:${i+1}`,`Число ${i+1}`,'2,85:1']),...[[1,2],[2,3],[3,4],[4,1]].map(([a,b])=>[`kwok:${a}:${b}`,`${a} или ${b}`,'0,95:1']),...[[1,2],[2,3],[3,4],[4,1]].map(([a,b])=>[`nim:${a}:${b}`,`Ним ${a} · возврат ${b}`,'1,90:1']),...Array.from({length:4},(_,i)=>[`triple:${i+1}`,`Все кроме ${i+1}`,'19:60'])];
function fanPayment(bet,result,stake){const [kind,a,b]=bet.split(':'),v=Number(a),push=Number(b);if(kind==='fan')return result===v?Math.round(stake*3.85):0;if(kind==='kwok')return (result===v||result===push)?Math.round(stake*1.95):0;if(kind==='nim')return result===v?Math.round(stake*2.9):result===push?stake:0;if(kind==='triple')return result!==v?Math.round(stake*(1+19/60)):0;return 0}
function fanHTML(){const r=rt.fantan;return extraPanel('✺ FAN TAN',`<div class="dice-three"><span class="die-face casino-big-number">${r?.result||'✦'}</span></div><div class="center-message">${r?.notice||'На какое число останется остаток при делении на четыре?'}</div><div class="panel-label">ВАРИАНТЫ СТАВОК · ${FAN_BETS.length}</div><div class="bet-option-grid">${FAN_BETS.map(([id,label,m])=>`<button class="mode-choice ${state.fantanBet===id?'active':''}" data-action="fan-pick" data-value="${id}">${label}<small>${m}</small></button>`).join('')}</div>${moreResult(r)}`,'✺ ОТСЧИТАТЬ','fan-play')}
function fanPlay(){const bet=state.fantanBet;if(!FAN_BETS.some(x=>x[0]===bet))return;morePlay('fantan',stake=>{const result=rnd(4)+1,payout=fanPayment(bet,result,stake);return{result,bet,stake,payout,notice:`Осталось ${result} · ${payout?'выплата '+money(payout):'проигрыш'}`}})}

const CROWN_SYMBOLS=['♛','⚓','★','♥','♦','♣'];
function crownPayment(result,selection,stake){const n=result.filter(v=>v===selection).length;return n?stake*(n+1):0}
function crownHTML(){const r=rt.crown;return extraPanel('⚓ CROWN & ANCHOR',`<div class="dice-three">${(r?.dice||[0,1,2]).map(n=>`<span class="die-face">${CROWN_SYMBOLS[n]}</span>`).join('')}</div><div class="center-message">${r?.notice||'Угадай символ на трёх кубиках'}</div><div class="bet-option-grid">${CROWN_SYMBOLS.map((s,i)=>`<button class="mode-choice ${state.crownBet===i?'active':''}" data-action="crown-pick" data-value="${i}">${s} ${['Корона','Якорь','Звезда','Черви','Бубны','Трефы'][i]}</button>`).join('')}</div>${moreResult(r)}`,'⚓ БРОСИТЬ КУБИКИ','crown-play')}
function crownPlay(){const pick=state.crownBet;if(!Number.isInteger(pick)||pick<0||pick>=6)return;morePlay('crown',stake=>{const dice=Array.from({length:3},()=>rnd(6)),payout=crownPayment(dice,pick,stake);return{dice,stake,payout,notice:`Совпадений: ${dice.filter(x=>x===pick).length} · выплата ${money(payout)}`}})}
const v17GameHTML=gameHTML;
gameHTML=function(){const views={caribbean:caribbeanHTML,teenpatti:teenHTML,fantan:fanHTML,crown:crownHTML};return views[state.game]?views[state.game]():v17GameHTML()};
const v17HandleBefore=handleAction;
handleAction=function(button){const a=button.dataset.action,v=button.dataset.value;
 switch(a){
 case 'caribbean-start':caribbeanStart();return;case 'caribbean-call':caribbeanFinish(true);return;case 'caribbean-fold':caribbeanFinish(false);return;
 case 'teen-pair':if(!rt.teenpatti?.active){state.teenPairPlus=!state.teenPairPlus;render()}return;
 case 'teen-start':teenStart();return;case 'teen-play':teenFinish(true);return;case 'teen-fold':teenFinish(false);return;
 case 'fan-pick':if(FAN_BETS.some(x=>x[0]===v)){state.fantanBet=v;render()}return;case 'fan-play':fanPlay();return;
 case 'crown-pick':if(Number.isInteger(Number(v))&&Number(v)>=0&&Number(v)<6){state.crownBet=Number(v);render()}return;case 'crown-play':crownPlay();return;
 case 'favorite-toggle':toggleFavorite(button.dataset.game);return;
 case 'favorites-filter':favoritesOnly=!favoritesOnly;syncGameSearch();return;
 case 'quality-toggle':qualityMode=qualityMode==='normal'?'lite':'normal';try{localStorage.setItem(QUALITY_STORAGE,qualityMode)}catch(e){}applyQualityMode();return;
 default:v17HandleBefore(button)
 }
};
// Persist only the independent visual preference, never alter game mechanics or RNG.
const QUALITY_STORAGE='neon-casino-quality-v1';
let qualityMode='normal';
try{
 const preference=localStorage.getItem(QUALITY_STORAGE);
 const lessMotion=typeof window!=='undefined'&&typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const limitedMemory=typeof navigator!=='undefined'&&typeof navigator.deviceMemory==='number'&&navigator.deviceMemory<=2;
 qualityMode=preference==='normal'||preference==='lite'?preference:(lessMotion||limitedMemory?'lite':'normal');
}catch(e){}
function applyQualityMode(){document.documentElement?.classList?.toggle('quality-lite',qualityMode==='lite');const b=document.getElementById('qualityToggle');if(b){b.textContent=qualityMode==='lite'?'⚡ ЭКО':'✧ ПЛАВНО';b.setAttribute('aria-pressed',String(qualityMode==='lite'));b.title='Переключить анимации: плавно / экономно'}}
applyQualityMode();
// Data exposed for QA cannot mutate balances or force a result.
restoreFavorites();restoreRecent();lastRenderedNavigation=null;render();renderRecent();
window.NEON_INFO=Object.freeze({version:'1.7.7',gameCount:GAMES.length,games:GAMES.map(g=>g.name),offline:true,virtualOnly:true});


// Cross-window ownership check on every modifying UI action.
const v171HandleAction=handleAction;
handleAction=function(button){
 const readonlyActions=new Set(['nav','wallet','close-modal','modal-overlay','history','daily-history','quality-toggle','favorite-toggle','favorites-filter']);
 if(!canModify()&&!readonlyActions.has(button.dataset.action)){leaseBlock();return}
 return v171HandleAction(button)
};
if(typeof window!=='undefined'&&typeof window.addEventListener==='function'){
 window.addEventListener('pagehide',()=>{
  if(!canModify())return;
  try{localStorage.removeItem(INSTANCE_KEY)}catch(e){}
 });
}
// Inactive windows never write the balance. Reload after closing the first one.
if(!instanceWritable){setTimeout(()=>leaseBlock(),100)}
else if(volatileMode){setTimeout(()=>toast('Локальное сохранение недоступно: прогресс останется только до закрытия окна.',true),100)}
else{setInterval(leaseHeartbeat,4000)}